import numpy as np,sys,time
from PIL import Image,ImageDraw
from paths import STROKES
T=np.array(Image.open('/app/target.png').convert('L').resize((512,512),Image.Resampling.BILINEAR))<125
P=[[list(x) for x in pts] for _,pts in STROKES]
N=len(P)

def draw(path):
 im=Image.new('1',(512,512),0);d=ImageDraw.Draw(im)
 for a,b in zip(path[:-1],path[1:]):
  n=max(1,int(np.hypot(b[0]-a[0],b[1]-a[1])*.7))
  for t in np.linspace(0,1,n):
   u,v,w=np.array(a)*(1-t)+np.array(b)*t
   u/=2;v/=2;r=max(.3,w/4)
   d.ellipse((u-r,v-r,u+r,v+r),fill=1)
 return np.asarray(im,dtype=bool)
M=[draw(p) for p in P]
def score(m):
 tp=np.count_nonzero(m&T);fp=np.count_nonzero(m&~T);fn=np.count_nonzero(~m&T)
 return tp/(tp+fp+fn),fp/T.sum(),tp/T.sum()
print('initial',score(np.logical_or.reduce(M)),flush=True)
orig=np.array([np.array(p,float) for p in P],dtype=object)
for sweep,delta in enumerate([10,6,3,2,1]):
 changed=0
 for si in range(N):
  others=np.logical_or.reduce([M[k] for k in range(N) if k!=si]); base=score(others|M[si])[0]
  for j in range(len(P[si])):
   for dim in [0,1,2]:
    best=(base,None,None)
    for dlt in [-delta,delta]:
     q=[x.copy() for x in P[si]];q[j][dim]+=dlt
     if dim==2 and not(2<=q[j][dim]<=65):continue
     if dim<2 and abs(q[j][dim]-orig[si][j][dim])>25:continue
     m=draw(q);s=score(others|m)[0]
     if s>best[0]+.00001:best=(s,q,m)
    if best[1] is not None:
     base,P[si],M[si]=best;changed+=1
 print('sweep',sweep,'changed',changed,'score',score(np.logical_or.reduce(M)),flush=True)
 np.save('/app/output/optimized_paths.npy',np.array(P,dtype=object),allow_pickle=True)
with open('/app/output/optimized_paths.py','w') as f:
 f.write('STROKES='+repr([(STROKES[i][0],[tuple(round(float(v),2) for v in x) for x in p]) for i,p in enumerate(P)])+'\n')
PY
